style.css:
@-moz-document domain("happyhalfyear.github.io") {
body {
        font-family: 'Montserrat', Arial, sans-serif !important;
        background: linear-gradient(135deg, #1e3c72, #2a5298) !important;
        color: #f0f0f0 !important;
        margin: 0 !important;
        padding: 0 !important;
        min-height: 100vh !important;
        display: flex !important;
        flex-direction: column !important;
    }

    /* Menu */
    .menu-bar {
        background-color: #111c2a !important;
        overflow: hidden !important;
        box-shadow: 0 2px 5px rgba(0,0,0,0.5) !important;
    }

    .menu-bar a {
        float: left !important;
        display: block !important;
        color: #f0f0f0 !important;
        text-align: center !important;
        padding: 14px 20px !important;
        text-decoration: none !important;
        font-weight: 600 !important;
        transition: background-color 0.3s, color 0.3s !important;
    }

    .menu-bar a:hover {
        background-color: #f39c12 !important;
        color: #111c2a !important;
    }

    .menu-bar a.icon {
        display: none !important;
    }

    @media screen and (max-width: 600px) {
        .menu-bar a {
            display: none !important;
            width: 100% !important;
            text-align: left !important;
        }
        .menu-bar a.icon {
            float: right !important;
            display: block !important;
            cursor: pointer !important;
        }
        .menu-bar.responsive {
            position: relative !important;
        }
        .menu-bar.responsive a {
            display: block !important;
            width: 100% !important;
            border-top: 1px solid #f39c12 !important;
        }
    }

    /* Header */
    header {
        background-color: transparent !important;
        padding: 40px 20px 20px 20px !important;
        text-align: center !important;
        position: relative !important;
    }

    header h1 {
        font-size: 3.5rem !important;
        margin: 0 !important;
        color: #f39c12 !important;
        text-shadow: 0 0 8px #f39c12, 0 0 20px #f39c12 !important;
        letter-spacing: 2px !important;
        animation: glow 2s ease-in-out infinite alternate !important;
        display: inline-block !important;
        position: relative !important;
    }

    header h1::after {
        content: "✨" !important;
        position: absolute !important;
        top: -10px !important;
        right: -30px !important;
        font-size: 2rem !important;
        animation: twinkle 3s infinite ease-in-out !important;
    }

    header h2 {
        margin-top: 10px !important;
        font-weight: 400 !important;
        font-size: 1.6rem !important;
        color: #f0d87d !important;
        text-shadow: 0 0 5px #f0d87d !important;
    }

    @keyframes glow {
        from {
            text-shadow: 0 0 5px #f39c12, 0 0 10px #f39c12;
        }
        to {
            text-shadow: 0 0 20px #f39c12, 0 0 30px #f39c12;
        }
    }

    @keyframes twinkle {
        0%, 100% { opacity: 1; transform: scale(1) rotate(0deg); }
        50% { opacity: 0.5; transform: scale(1.2) rotate(20deg); }
    }

    /* Main */
    main {
        padding: 20px 30px !important;
        flex-grow: 1 !important;
        max-width: 900px !important;
        margin: 0 auto !important;
        background-color: rgba(0, 0, 0, 0.3) !important;
        border-radius: 15px !important;
        box-shadow: 0 0 30px rgba(243, 156, 18, 0.6) !important;
    }

    section {
        margin-bottom: 30px !important;
    }

    h2 {
        color: #f39c12 !important;
        border-bottom: 2px solid #f39c12 !important;
        padding-bottom: 8px !important;
        margin-bottom: 15px !important;
    }

    p {
        font-size: 1.15rem !important;
        line-height: 1.6 !important;
        color: #f0f0f0 !important;
    }

    /* Plan wydarzenia */
    .plan {
        background: rgba(243, 156, 18, 0.15) !important;
        padding: 15px 20px !important;
        border-radius: 10px !important;
        font-style: italic !important;
        color: #fff !important;
        box-shadow: inset 0 0 10px rgba(243, 156, 18, 0.5) !important;
    }

    /* Przycisk */
    .btn-celebrate {
        display: inline-block !important;
        background-color: #f39c12 !important;
        color: #111c2a !important;
        font-weight: 700 !important;
        padding: 12px 30px !important;
        border-radius: 30px !important;
        text-decoration: none !important;
        font-size: 1.2rem !important;
        box-shadow: 0 0 20px #f39c12 !important;
        transition: background-color 0.3s, color 0.3s !important;
        margin-top: 15px !important;
        user-select: none !important;
    }
    
    .btn-celebrate:hover {
        background-color: #e67e22 !important;
        color: #fff !important;
        box-shadow: 0 0 25px #e67e22 !important;
    }

    /* Footer */
    footer {
        text-align: center !important;
        padding: 15px !important;
        background-color: #111c2a !important;
        color: #f39c12 !important;
        font-weight: 600 !important;
        box-shadow: 0 -2px 5px rgba(0,0,0,0.6) !important;
    }

    /* Fajerwerki w tle - CSS */
    body::before {
        content: "" !important;
        position: fixed !important;
        top: 0 !important;
        left: 0 !important;
        width: 100% !important;
        height: 100% !important;
        pointer-events: none !important;
        background:
            radial-gradient(circle at 20% 30%, rgba(243, 156, 18, 0.3) 10px, transparent 11px),
            radial-gradient(circle at 80% 40%, rgba(243, 156, 18, 0.25) 8px, transparent 9px),
            radial-gradient(circle at 50% 80%, rgba(243, 156, 18, 0.2) 12px, transparent 13px) !important;
        background-repeat: no-repeat !important;
        animation: flicker 3s infinite alternate !important;
        z-index: 0 !important;
    }

    @keyframes flicker {
        0% {opacity: 0.4;}
        100% {opacity: 0.8;}
    }
}
